 * Longest common subsequence matching between two documents (arrays of
 * strings), comparing lines as exact strings.
 *
 * When multiple longest common subsequences exist, the one returned is the
 * one whose matches come earliest: walking both documents from the start, a
 * match is taken whenever the two current lines are equal, and otherwise the
 * side whose remaining subsequence is at least as long as the other's is
 * advanced, preferring to advance the base (the second argument) when they
 * tie.
 *
 * Returns an array of [sideIndex, baseIndex] pairs, in increasing order of
 * both indices.
 */
export function lcsMatches(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] = length of the LCS of side[i:] and base[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const advanceSide = dp[i + 1][j]
        const advanceBase = dp[i][j + 1]
        dp[i][j] = advanceSide > advanceBase ? advanceSide : advanceBase
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceSide = dp[i + 1][j]
      const advanceBase = dp[i][j + 1]
      if (advanceSide > advanceBase) {
        i++
      } else {
        j++
      }
    }
  }
  return matches
}
"}

