/**
 * The changes one side made relative to the base, derived from the LCS
 * match between them. Each change describes a run of base lines (from
 * `start`, inclusive, to `end`, exclusive, both indices into the base
 * document) replaced by `lines`, this side's lines for that stretch. An
 * insertion has `start === end`; a deletion has `lines.length === 0`.
 */
export function changesAgainstBase(side, base) {
  const matches = lcsMatches(side, base)
  const changes = []
  let prevSi = -1
  let prevOi = -1
  for (const [si, oi] of matches.concat([[side.length, base.length]])) {
    if (si > prevSi + 1 || oi > prevOi + 1) {
      changes.push({ start: prevOi + 1, end: oi, lines: side.slice(prevSi + 1, si) })
    }
    prevSi = si
    prevOi = oi
  }
  return changes
}
"}

