  const theirsChanges = changesAgainstBase(theirs, base).map(c => ({ ...c, side: 'theirs' }))

  const allChanges = mineChanges
    .concat(theirsChanges)
    .sort((a, b) => {
      if (a.start !== b.start) return a.start - b.start
      if (a.side === b.side) return 0
      return a.side === 'mine' ? -1 : 1
